// >>> Onda de JANELA ABERTA, bloco J1 (18/08/2026). O Gui autorizou quebrar a
// save dele, porque o Chapter Jump repoe o progresso em minutos. Este e o
// UNICO crescimento de FLAGS_COUNT da onda, e tudo entra em APPEND depois da
// FLAG_RESERVA_HISTORIA: nenhuma flag ja apelidada muda de valor, nenhum
// endereco anterior desliza.
//
// A conta, medida em 18/08/2026 e nao chutada:
//   teto duro do setor de save   15872 B  (SECTOR_DATA_SIZE 3968 x setores 1 a
//                                          4, include/save.h; STATIC_ASSERT
//                                          SaveBlock1FreeSpace em src/save.c)
//   teto do plano desta onda      15395 B  (97% do setor)
//   SaveBlock1 ANTES              14388 B  (90,7%) -> 1007 B de crescimento
//   custo deste bloco               576 B  (4608 flags, 8 flags por byte)
//   SaveBlock1 DEPOIS             14964 B  (94,3%) -> sobram 431 B ate os 97%
//
// Segundo teto, o que ninguem lembra: SPECIAL_FLAGS_START e 0x4000, e flag de
// SAVE nunca pode alcancar esse numero, senao id de flag salva colide com as
// flags especiais que moram na EWRAM. Depois deste bloco FLAGS_COUNT e 0x3238,
// ou seja ainda ha 0xDC8 de folga arquitetural. Os dois tetos ficam quase
// empatados: 1007 B pelo setor contra 1017 B pelo 0x4000, e quem aperta
// primeiro e o setor.

// Faixa das item balls de Johto, Sinnoh e Unova (bloco J2 desta onda).
// MEDIDO em 18/08/2026 varrendo data/maps/*/map.json: 1431 object events com
// OBJ_EVENT_GFX_ITEM_BALL e campo `flag` igual a 0. Flag 0 nunca persiste,
// entao a bola renasce a cada entrada no mapa e o item duplica sem limite.
// Dessas 1431, 48 sao do Battle Pyramid de Hoenn (gMapGroup_IndoorDynamic),
// que e dinamico de proposito e NAO deve ganhar flag: a demanda real e 1383.
// O plano da onda falava em 1362; a diferenca esta anotada no relatorio do J1.
// A faixa e de 1536 para o J2 caber com folga sem precisar de outra janela.
//
// Ela NAO e declarada uma a uma de proposito, igual as duas faixas de item de
// Kanto e de Unova logo acima: quem gera os apelidos por regiao e o J2.
//
// A ESTIMATIVA ACIMA MORREU. O J2 mediu e a demanda real era 160, nao 1383:
// os 1372 achatados nao dao item nenhum (script "0"), e cruzados por
// coordenada com a fonte `hns` so 161 sao BOLA de verdade. Gravadas 160
// (0x2031-0x20D0). O J7 redeclarou a sobra 0x20D1-0x2630 (1376 vagas) como
// reserva de conteudo, em FLAG_SOBRA_ITEM_BALLS_START, sem mexer em endereco
// nenhum: a faixa continua deste tamanho, o dono da segunda parte e que mudou.
#define FLAG_ITEM_BALLS_JSU_START                   (FLAG_RESERVA_HISTORIA_START + NUM_RESERVA_HISTORIA)
#define NUM_ITEM_BALLS_JSU                          0x600 // 1536

// Folga de conteudo declarada, segunda metade do J1.
//
// Demanda que ela cobre, com numero em cima de cada uma:
//   - Galar: fila de 3.257 linhas em dev_scripts/fila_galar.json (2.641
//     script_objeto, 256 map_script, 226 porta_morta, 134 placa). Nem toda
//     linha vira flag, mas NPC de cena pede flag de esconder, e errar para
//     cima aqui e barato porque a janela so abre uma vez.
//   - Johto: a faixa 0x1840-0x18FF acabou (192 de 192) e vive do transbordo
//     0x1D00-0x1D3F, que tem 62 vagas.
//   - Wild Area e as cenas que ainda nao foram escritas nas cinco regioes.
// O pool velho tinha 1322 flags realmente livres (dev_scripts/flags_livres.py
// em 18/08/2026); com estas 3072 ele passa a 4394.
//
// Declaradas uma a uma, como a RESERVA_HISTORIA de 12/08/2026, porque
// flags_livres.py so enxerga o que existe como `#define FLAG_UNUSED_0xNNNN`.
// Faixa declarada em bloco seria pool invisivel para a ferramenta que
// distribui flag entre agentes. Como usar: nunca escreva o numero, apelide.
#define FLAG_RESERVA_CONTEUDO_START                 (FLAG_ITEM_BALLS_JSU_START + NUM_ITEM_BALLS_JSU)
#define NUM_RESERVA_CONTEUDO                        0xC00 // 3072

