// As duas flags de esconder o Pokemon de dia e o de noite de Goldenrod, bloco
// J8 da onda de janela aberta (18/08/2026). Elas ja existiam, mas como STUB do
// import de Johto: `#ifndef FLAG_NIGHT_POKEMON / #define FLAG_NIGHT_POKEMON
// 0x4000`, numero cru inventado para o build fechar. 0x4000 e
// SPECIAL_FLAGS_START, ou seja o stub cravava FLAG_HIDE_MAP_NAME_POPUP (citada
// em 17 arquivos) e FLAG_DONT_TRANSITION_MUSIC (9 arquivos), e as duas do stub
// estavam VIVAS no campo `flag` de object event em
// data/maps/GoldenrodCity_UndergroundTunnel/map.json e
// data/maps/GoldenrodCity_DepartmentStore_5F/map.json. O NPC sumia do mapa toda
// vez que o motor acendia a flag dele, e um `removeobject` nele acenderia a
// flag do motor. Pior: SPECIAL_FLAGS mora na EWRAM (sSpecialFlags,
// src/event_data.c:28) e NAO persiste, entao o endereco estava errado ate como
// flag de objeto.
//
// Por que 0x1D01 e 0x1D02, e nao a FLAG_RESERVA_CONTEUDO do J1: elas sao
// conteudo de JOHTO e escondem object event, exatamente como
// FLAG_HIDE_LAKE_OF_RAGE_GYARADOS logo acima. O transbordo desta regiao ja e
// 0x1D00-0x1D3F, e ele tinha 63 vagas livres em 18/08/2026 (medido com
// dev_scripts/flags_livres.py, faixa contigua "0x1D01 a 0x2025"). Gastar a
// reserva do J1, que nasceu dimensionada para Galar e Wild Area, espalharia
// Johto por uma terceira faixa sem ganhar nada. Apelidar FLAG_UNUSED que ja
// existe nao mexe em FLAGS_COUNT: o tamanho da save NAO muda com este bloco.
//
// O nome vem do import de HGSS e fica: os tres usos em map.json referenciam o
// NOME, entao nenhum map.json precisou mudar. Nada no motor acende as duas
// (nao ha relogio de dia e noite nesta ROM), logo os dois NPCs ficam sempre
// visiveis; a entrega do J8 e o ENDERECO, nao o desenho de dia e noite.
#define FLAG_NIGHT_POKEMON                                   FLAG_UNUSED_0x1D01
#define FLAG_DAY_POKEMON                                     FLAG_UNUSED_0x1D02
