// EventScript_ResetAllMapFlags: apagada e o estado de jogo novo, e a cena a
// acende quando o jogador aceita a vara. Nao reusa FLAG_RECEIVED_GOOD_ROD
// porque aquela e do pescador da Route 118, de HOENN, e as duas cenas sao
// independentes; quem ja pegou a vara la e barrado pelo `checkitem` da cena.
