// <<< Onda de JANELA ABERTA, bloco J2 <<<

// >>> Onda de JANELA ABERTA, bloco J7 (18/08/2026): a SOBRA da faixa de item
// ball, redeclarada como reserva de conteudo >>>
//
// DONO: a reserva de conteudo geral (mesmo dono da FLAG_RESERVA_CONTEUDO do
// J1). Antes disto o dono anotado era "item balls", e era mentira.
//
// MOTIVO, e a conta que o derrubou: o J1 reservou 0x2031-0x2630 (1536 vagas)
// em cima da estimativa de ~1383 item balls, tirada de "1431 object events com
// OBJ_EVENT_GFX_ITEM_BALL e flag 0, menos os 48 do Battle Pyramid". A MEDICAO
// do J2 derrubou a estimativa: dos 1372 achatados, 1364 casam por coordenada
// com a fonte `hns` e so 161 sao BOLA na fonte. O resto e efeito de luz (219),
// pedra de Rock Smash, canteiro de berry, Pokemon de overworld e NPC, ou seja
// nunca vai virar item ball. O bloco J2 acima gravou 160 (0x2031-0x20D0; a
// 161a e a GS Ball, que ficou de fora porque ITEM_GS_BALL nao existe no
// expansion). Sobraram 1376 vagas com dono errado.
//
// CUSTO ZERO DE SAVE, de proposito: isto e mudanca de COMENTARIO e de
// DECLARACAO. FLAGS_COUNT continua 0x3238, a faixa continua no mesmo lugar,
// FLAG_RESERVA_CONTEUDO_START continua sendo FLAG_ITEM_BALLS_JSU_START +
// NUM_ITEM_BALLS_JSU (0x2631), e nenhum endereco ja gravado desliza. So o
// nome do dono muda, mais 1376 FLAG_UNUSED que antes nao existiam.
//
// Declaradas UMA A UMA pelo mesmo motivo da RESERVA_CONTEUDO do J1:
// `dev_scripts/flags_livres.py` so enxerga o que existe como
// `#define FLAG_UNUSED_0xNNNN`. Faixa declarada em bloco seria pool invisivel
// para a ferramenta que distribui flag entre agentes, e o proposito aqui e
// justamente devolver estas 1376 ao pool. Como usar: nunca escreva o numero,
// apelide.
//
// Quem gerar item ball nova NAO pode entrar aqui em append: o
// `dev_scripts/liga_bolas_johto.py` tem guarda que reprova se o proximo offset
// alcancar FLAG_SOBRA_ITEM_BALLS_START, e o portao de colisao de flags
// (`dev_scripts/guarda_colisao_vars.py --flags`) acusa o dono dobrado.
//
// LEVA DE ENCERRAMENTO, 19/08/2026: a fronteira andou UM, de 0x0A0 para 0x0A1,
// porque a bola AUSENTE de OlivineCity_Lighthouse (125,15) virou objeto e
// precisou de endereco proprio. O metodo e o unico que preserva o invariante
// desta faixa (o nome FLAG_UNUSED_0xNNNN E o endereco NNNN): a linha
// FLAG_UNUSED_0x20D1 foi APAGADA, virou dona do bloco J2, e os 1375 offsets
// restantes desceram 1, de modo que cada nome continua valendo exatamente o
// numero que carrega. Conferido linha a linha na hora da mudanca e provado
// depois pelo portao de colisao de flags, que resolve pelo pre-processador e
// nao pelo texto. CUSTO ZERO DE SAVE: FLAGS_COUNT nao mudou.
#define FLAG_SOBRA_ITEM_BALLS_START                 (FLAG_ITEM_BALLS_JSU_START + 0x0A1)
#define NUM_SOBRA_ITEM_BALLS                        0x55F // 1375

#define FLAG_UNUSED_0x20D2                  (FLAG_SOBRA_ITEM_BALLS_START + 0x000)
